"""Preserve initial harness evidence and its generated bytecode outside canonical source."""
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
SOURCE = HERE / "incoming_source"
baseline = json.loads((HERE / "STAGING_RECEIPT.json").read_text())["revision"]
extra = [p for p in SOURCE.rglob("*") if p.is_file() and p.relative_to(SOURCE).as_posix() not in baseline]
if any(p.suffix != ".pyc" or p.parent.name != "__pycache__" for p in extra):
    raise ValueError("Unexpected source artifact; refuse cleanup")
if any(hashlib.sha256((SOURCE / k).read_bytes()).hexdigest() != v["sha256"] for k, v in baseline.items()):
    raise ValueError("Original source changed")
target = HERE / "initial_probe_generated_bytecode"
if target.exists():
    raise ValueError("Initial evidence already preserved")
for p in extra:
    dest = target / p.relative_to(SOURCE)
    dest.parent.mkdir(parents=True, exist_ok=True)
    p.rename(dest)
for p in sorted(SOURCE.rglob("__pycache__"), reverse=True):
    if not any(p.iterdir()):
        p.rmdir()
for name in ("DATED_REVISION_READINESS_EVIDENCE.json", "UPSTREAM_REGRESSION_TEST_LOG.txt"):
    old, new = HERE / name, HERE / ("INITIAL_HARNESS_" + name)
    if new.exists():
        raise ValueError("Refuse evidence overwrite")
    old.rename(new)
print(f"Preserved initial evidence and {len(extra)} generated bytecode files; original source unchanged")
